<?php require __DIR__.'/../includes/bootstrap.php'; $msg='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$email=post('email');$found=false;foreach(['admin','teacher','student','parent','librarian','accountant','hostel'] as $t){$q=$db->prepare("SELECT * FROM `$t` WHERE email=? LIMIT 1");$q->bind_param('s',$email);$q->execute();$r=$q->get_result()->fetch_assoc();if($r){$new=bin2hex(random_bytes(4));$u=$db->prepare("UPDATE `$t` SET password=? WHERE email=?");$u->bind_param('ss',$new,$email);$u->execute();$msg='A new password was generated. Configure your mail server before enabling email delivery. Temporary password: '.$new;$found=true;break;}}if(!$found)$msg='No account was found for that email address.';}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Forgot Password</title><link rel="stylesheet" href="assets/css/app.css"></head><body class="login"><div class="panel"><h2>Forgot Password</h2><?php if($msg): ?><div class="alert success"><?=e($msg)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><p><label>Email</label><input type="email" name="email" required></p><button class="btn">Reset Password</button> <a href="login.php">Back to Login</a></form></div></body></html>